<?php require 'config/auth.php';wajib_login();require 'config/database.php';$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$pw=$_POST['password']??'';if($u==='')$err='Username wajib diisi.';else{$id=(int)$_SESSION['user'];if($pw!==''&&strlen($pw)<5)$err='Password minimal 5 karakter.';else{if($pw!==''){$hash=password_hash($pw,PASSWORD_DEFAULT);$st=$conn->prepare('UPDATE users SET username=?,password=? WHERE id=?');$st->bind_param('ssi',$u,$hash,$id);}else{$st=$conn->prepare('UPDATE users SET username=? WHERE id=?');$st->bind_param('si',$u,$id);}if($st->execute()){$_SESSION['username']=$u;$msg='Pengaturan akun berhasil diperbarui.';}else $err='Username sudah digunakan.';}}}$role=$_SESSION['role'];$back=$role==='admin'?'admin/index.php':($role==='guru'?'guru/index.php':'siswa/index.php');?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profil SIPN</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="profile-page"><main class="main"><a class="back" href="<?=$back?>">← Home</a><section class="panel"><h1>Profile & Pengaturan</h1><p>Informasi akun</p><p>Username: <b><?=h($_SESSION['username'])?></b></p><p>Role: <b><?=h($role)?></b></p><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert"><?=$err?></div><?php endif;?><h2>Edit kredensial akun</h2><form method="post" class="data-form"><label>Username baru</label><input name="username" value="<?=h($_SESSION['username'])?>" required><label>Password baru (kosongkan jika tidak diganti)</label><input type="password" name="password" placeholder="Password baru (opsional)"><button class="btn primary">Simpan Pengaturan</button></form><p><a href="logout.php">Logout</a></p></section></main></body></html>